#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
extern "C" int solve_assignment(const double* c,int n,int* out){
 for(int k=64;;k=std::min(n,k*2)){
  std::vector<int> ix((long long)n*k);
  #pragma omp parallel for
  for(int i=0;i<n;i++){
   int* z=ix.data()+(long long)i*k;
   // Keep k smallest using an index workspace.
   std::vector<int> all(n); std::iota(all.begin(),all.end(),0);
   if(k<n) std::nth_element(all.begin(),all.begin()+k,all.end(),[&](int x,int y){return c[(long long)i*n+x]<c[(long long)i*n+y];});
   std::copy(all.begin(),all.begin()+k,z);
  }
  std::vector<double> p(n,0.0); std::vector<int> own(n,-1),asg(n,-1),q; q.reserve(n*50);
  for(double eps=.02;eps>1e-12;eps*=.1){
   std::fill(own.begin(),own.end(),-1);std::fill(asg.begin(),asg.end(),-1);q.resize(n);std::iota(q.begin(),q.end(),0);
   size_t h=0;
   while(h<q.size()){
    int i=q[h++],j1=-1;double v1=1e100,v2=1e100; const int* z=ix.data()+(long long)i*k;
    for(int x=0;x<k;x++){int j=z[x];double v=c[(long long)i*n+j]+p[j];if(v<v1){v2=v1;v1=v;j1=j;}else if(v<v2)v2=v;}
    p[j1]+=v2-v1+eps;int old=own[j1];own[j1]=i;asg[i]=j1;if(old>=0)q.push_back(old);
   }
  }
  // Full reduced-cost certificate. Tiny epsilon guarantees unique exact optimum.
  bool good=true;
  for(int i=0;i<n&&good;i++){double v=c[(long long)i*n+asg[i]]+p[asg[i]];for(int j=0;j<n;j++)if(c[(long long)i*n+j]+p[j]<v-1e-10){good=false;break;}}
  if(good||k==n){std::copy(asg.begin(),asg.end(),out);return good;}
 }
}
