#include <vector>
#include <algorithm>
#include <numeric>
extern "C" void ass(const double*c,int n,int*out){
 std::vector<double> p(n,0);std::vector<int> own(n,-1),a(n,-1),q;q.reserve(n*20);
 for(double e=.1;e>1e-9;e*=.1){
  q.clear();
  if(e==.1){for(int i=0;i<n;i++)q.push_back(i);}
  else for(int i=0;i<n;i++){
   const double*r=c+(long long)i*n; double best=1e100;for(int j=0;j<n;j++)best=std::min(best,r[j]+p[j]);
   if(r[a[i]]+p[a[i]]>best+e){own[a[i]]=-1;a[i]=-1;q.push_back(i);}
  }
  size_t h=0;while(h<q.size()){int i=q[h++];const double*r=c+(long long)i*n;double x=1e100,y=1e100;int jj=-1;
   for(int j=0;j<n;j++){double v=r[j]+p[j];if(v<x){y=x;x=v;jj=j;}else if(v<y)y=v;}
   p[jj]+=y-x+e;int old=own[jj];own[jj]=i;a[i]=jj;if(old>=0){a[old]=-1;q.push_back(old);}
  }
 }
 std::copy(a.begin(),a.end(),out);
}
